package config

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"gopkg.in/yaml.v3"
)

// StateFileName is the settings file ai-swap keeps next to its config.
const StateFileName = "state.yaml"

// State is the part of a node's configuration that can be changed at runtime
// (from the API or the UI). ai-swap writes it to state.yaml next to
// config.yaml and reads it on top of the config at startup, so the config
// file itself is never rewritten: it may be generated by another tool (such
// as llama-config) and regenerating it leaves these settings in place.
//
// A nil field is not overridden: the config's value applies.
type State struct {
	// Resident replaces node.resident when set; an empty list means none.
	Resident *[]string `yaml:"resident,omitempty" json:"resident"`
	// DefaultModel replaces node.default_model when set; "" clears it.
	DefaultModel *string `yaml:"default_model,omitempty" json:"default_model"`
}

// IsZero reports whether the state overrides nothing.
func (s State) IsZero() bool { return s.Resident == nil && s.DefaultModel == nil }

// StatePath is where the state file for a config file lives.
func StatePath(configPath string) string {
	return filepath.Join(filepath.Dir(configPath), StateFileName)
}

// LoadState reads a state file. A missing file is an empty state.
func LoadState(path string) (State, error) {
	var st State
	b, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return st, nil
	}
	if err != nil {
		return st, err
	}
	dec := yaml.NewDecoder(bytes.NewReader(b))
	dec.KnownFields(true)
	if err := dec.Decode(&st); err != nil && !errors.Is(err, io.EOF) {
		return st, fmt.Errorf("parse %s: %w", path, err)
	}
	return st, nil
}

const stateHeader = `# Written by ai-swap: settings changed from its API or UI (resident models,
# default model). They apply on top of config.yaml, which ai-swap never
# rewrites. Delete a key (or the file) to go back to config.yaml's value.
`

// SaveState writes the state file atomically. An empty state removes it.
func SaveState(path string, st State) error {
	if st.IsZero() {
		if err := os.Remove(path); err != nil && !errors.Is(err, os.ErrNotExist) {
			return err
		}
		return nil
	}
	b, err := yaml.Marshal(st)
	if err != nil {
		return err
	}
	tmp, err := os.CreateTemp(filepath.Dir(path), ".state-*.yaml")
	if err != nil {
		return err
	}
	defer os.Remove(tmp.Name())
	if _, err := tmp.WriteString(stateHeader); err == nil {
		_, err = tmp.Write(b)
	}
	if cerr := tmp.Close(); err == nil {
		err = cerr
	}
	if err != nil {
		return err
	}
	return os.Rename(tmp.Name(), path)
}

// CheckResident validates a resident list against the config: every name
// must be a model (aliases are canonicalised), listed once, and together they
// must fit in the memory budget. It returns the canonical names.
func (c *Config) CheckResident(names []string) ([]string, error) {
	out := make([]string, 0, len(names))
	seen := map[string]bool{}
	var gb float64
	for _, n := range names {
		m, ok := c.Resolve(n)
		if !ok {
			return nil, fmt.Errorf("unknown model %q", n)
		}
		if seen[m.Name] {
			return nil, fmt.Errorf("%q listed twice", n)
		}
		seen[m.Name] = true
		gb += m.MemoryGB
		out = append(out, m.Name)
	}
	if c.Node.MemoryBudgetGB > 0 && gb > c.Node.MemoryBudgetGB {
		return nil, fmt.Errorf("resident models need %.0f GB together, over the node budget %.0f GB", gb, c.Node.MemoryBudgetGB)
	}
	return out, nil
}

// ApplyState lays st over the config. Settings that no longer fit the config
// (a model since removed from it, residents over a lowered budget) are
// skipped rather than failing startup: the config's value applies and a
// warning is returned for each.
func (c *Config) ApplyState(st State) (warnings []string) {
	if st.Resident != nil {
		if names, err := c.CheckResident(*st.Resident); err != nil {
			warnings = append(warnings, "state resident ignored: "+err.Error())
		} else {
			c.Node.Resident = names
		}
	}
	if st.DefaultModel != nil {
		// A pinned peer model ("model@node") can't be checked until the
		// peers are up; a local one must exist.
		if d := *st.DefaultModel; d != "" && !strings.Contains(d, "@") {
			if m, ok := c.Resolve(d); ok {
				c.Node.DefaultModel = m.Name
			} else {
				warnings = append(warnings, fmt.Sprintf("state default_model ignored: unknown model %q", d))
			}
		} else {
			c.Node.DefaultModel = d
		}
	}
	return warnings
}
